{
  "root_cause": "The tabbable library does not check whether a form control lives inside a disabled <fieldset>. The dialog's "Delivery speed" <select> is inside a disabled fieldset, so the browser refuses to focus it, but tabbable() still returns it as the first tabbable node. When the focus trap activates, it tries to focus that <select>, the focus call silently fails, and focus remains on the trigger button.",
  "repair_strategy": "Add an isInDisabledFieldset helper that walks up the DOM tree looking for a disabled <fieldset> ancestor, and integrate it into isNodeMatchingSelectorFocusable so elements inside disabled fieldsets are excluded from the tabbable list. This makes the first tabbable node the street address <input>, which the browser can focus.",
  "edits": [
    {
      "path": "src/index.js",
      "sha256": "8f69e239e7365811abad1130954bb9d4772c0f0e31c477f37f22a3644de78652",
      "before": "const isHidden = function (node, displayCheck) {
  if (getComputedStyle(node).visibility === 'hidden') {
    return true;
  }

  const isDirectSummary = matches.call(node, 'details>summary:first-of-type');
  const nodeUnderDetails = isDirectSummary ? node.parentElement : node;
  if (matches.call(nodeUnderDetails, 'details:not([open]) *')) {
    return true;
  }
  if (!displayCheck || displayCheck === 'full') {
    while (node) {
      if (getComputedStyle(node).display === 'none') {
        return true;
      }
      node = node.parentElement;
    }
  } else if (displayCheck === 'non-zero-area') {
    const { width, height } = node.getBoundingClientRect();
    return width === 0 && height === 0;
  }

  return false;
};

const isNodeMatchingSelectorFocusable = function (options, node) {
  if (
    node.disabled ||
    isHiddenInput(node) ||
    isHidden(node, options.displayCheck) ||
    /* For a details element with a summary, the summary element gets the focused  */
    isDetailsWithSummary(node)
  ) {
    return false;
  }
  return true;
};",
      "after": "const isHidden = function (node, displayCheck) {
  if (getComputedStyle(node).visibility === 'hidden') {
    return true;
  }

  const isDirectSummary = matches.call(node, 'details>summary:first-of-type');
  const nodeUnderDetails = isDirectSummary ? node.parentElement : node;
  if (matches.call(nodeUnderDetails, 'details:not([open]) *')) {
    return true;
  }
  if (!displayCheck || displayCheck === 'full') {
    while (node) {
      if (getComputedStyle(node).display === 'none') {
        return true;
      }
      node = node.parentElement;
    }
  } else if (displayCheck === 'non-zero-area') {
    const { width, height } = node.getBoundingClientRect();
    return width === 0 && height === 0;
  }

  return false;
};

const isInDisabledFieldset = function (node) {
  let parent = node.parentElement;
  while (parent) {
    if (parent.tagName === 'FIELDSET' && parent.disabled) {
      return true;
    }
    parent = parent.parentElement;
  }
  return false;
};

const isNodeMatchingSelectorFocusable = function (options, node) {
  if (
    node.disabled ||
    isHiddenInput(node) ||
    isHidden(node, options.displayCheck) ||
    isInDisabledFieldset(node) ||
    /* For a details element with a summary, the summary element gets the focused  */
    isDetailsWithSummary(node)
  ) {
    return false;
  }
  return true;
};"
    }
  ],
  "expected_accessibility_effect": "Keyboard users opening the dialog will now have focus correctly land on the first truly focusable field (the street address input) per WCAG 2.1.1 and 2.4.3, instead of being stranded on the trigger button.",
  "functional_risks": [
    "Minimal; the change only removes elements from the tabbable list that browsers already refuse to focus. No behavior changes for enabled fieldsets or other containers."
  ],
  "verification_requirements": [
    "Run the journey again; the "Open address dialog" step should pass its focus assertion on #street.",
    "The regression guard (Escape closes dialog) should still pass."
  ]
}

